import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"49、【革】 离下兑上","description":"周易口诀义 - 49、【革】 离下兑上","frontmatter":{"title":"49、【革】 离下兑上","description":"周易口诀义 - 49、【革】 离下兑上"},"headers":[],"relativePath":"zh/classics/koujueyi/051.md","filePath":"zh/classics/koujueyi/051.md"}'),r={name:"zh/classics/koujueyi/051.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_49、【革】-离下兑上" tabindex="-1">49、【革】 离下兑上 <a class="header-anchor" href="#_49、【革】-离下兑上" aria-label="Permalink to “49、【革】 离下兑上”">​</a></h1><p>彖曰：革，水火相息，二女同居，其志不相得，曰「革」。「巳日乃孚」，革而信之。文明以说，大亨以正，革而当，其悔乃亡。天地革而四时成，汤武革命，顺乎天而应乎人，革之时大矣哉！</p><p>象曰：泽中有火，革。君子以治历明时。</p><p>初九：巩用黄牛之革。</p><p>象曰：「巩用黄牛」，不可以有为也。</p><p>六二：巳日乃革之，征吉，无咎。</p><p>象曰：「巳日革之」，行有嘉也。</p><p>九三：征凶，贞厉。革言三就，有孚。</p><p>象曰：「革言三就」，又何之矣。</p><p>九四，悔亡，有孚，改命吉。</p><p>象曰：改命之「吉」，信志也。</p><p>九五，大人虎变，未占有孚。</p><p>象曰：「大人虎变」，其文炳也。</p><p>上六，君子豹变，小人革面，征凶，居贞吉。</p><p>象曰：「君子豹变」，其文蔚也；「小人革面」，顺以从君也。</p><p>解读</p><p>「革巳日乃孚」者，革，改变之名，易旧之义，故名「革」也。革既改旧易新，即是王者创制命令，改前王之法度。以其初施法令，民有所感，未便从伏，必须已竟今日，明日方始从令。故宋衷云：人性习常，不说改易，及变之后，乐其所成，故即日不孚，巳日乃孚矣，故曰「巳日乃孚」也。已，竟也。「元亨利贞，悔亡」者，悔之所生，生乎变动也。今革既变，故人心不安，必有忧悔。今革道既当，即得大通利正，而忧悔乃亡，故须备此四德矣。象曰「泽中有火，革」者，火居泽下，火炎上，泽润下，二性交，故能变革也。「君子以治历明时」者，寒暑迭终，日月更运，天时人事，各以时迁，故君子观兹革象，修治历数，以明天时也。</p><p>「初九，巩用黄牛之革」者，巩，固也；黄，中也；革是牛皮，生曰革，熟曰韦。今初九处革之初，未肯从变，言其执志坚固，守中和之道，不肯造次从变，如似牛皮坚韧，不从改变之命也。</p><p>「六二，巳日乃革之，征吉，无咎」者，阴柔之体，不敢为先，故革命已行，竟日之后，乃始从之，故曰「巳日乃革之」。既从革命，无复疑阻，往就于五，不被疑难，故可以征进而获无咎也。</p><p>「九三，征凶，贞厉，革言三就，有孚」者，三处炎极，火性上炎，上体是水，水性柔顺，九三以刚居火极，火性刚猛，故有革命之言。而上体三爻，以受命令，不敢有违，其言不虚，故曰「革言三就，有孚」也。人既从命，更兴征伐，即是非理兴师，所以致凶。夫兴师动众，是正道之危，故曰「征凶，贞厉」也。</p><p>「九四，悔亡，有孚改命，吉」者，无应，故有忧悔，能从革命，故曰「悔亡」也。居水火之际，不为固吝，信彼改命之制，合时之愿，所以获吉，故曰「有孚，改命，吉」也。</p><p>「九五：大人虎变，未占有孚」者，居得尊位，以大人之德为革之主，即是革去前王之命，为新创之君，信德自著，合人之心，不劳占决，斯汤武之君是也。「虎变」者，谓改正朔，易服色，取其文章炳焕，又取虎之威猛可畏之义也。</p><p>「上六：君子豹变，小人革面，征凶，居贞吉」者，处革之极，变道已成，君子居之，虽不如大人之变，如虎之文，然亦可顺时而行，如豹文之映蔚，故曰「君子豹变」也。若小人处之，但能变其颜面，顺上而已，故曰「小人革面」也。革变已极，人皆从命，固宜静处，而更以征伐为求，即是躁扰于人，所以致凶。如静而居之，皆获吉，故曰「征凶，居贞吉」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
